import { seededRoll } from './world.js';

// Two personal scenes per participant per year, plus actual consequence returns.
// Selection uses saved facts and never asks a model to invent events at runtime.
export const PERSONAL_TOPICS=Object.freeze([
  ['unfired','An unfired cup','has made a clay cup that cracked before firing. They keep using it to hold small things.','Ask why they kept it','Because it is the first thing I made without waiting for someone to tell me I could.'],
  ['sleep','A lamp left burning','has been working late and missing the small hours of home. A lamp has been left burning for a conversation that never happened.','Ask who has been waiting','Someone who does not need another account of my work. I ought to ask about theirs.'],
  ['departure','A road postponed','has delayed a journey twice. The household is ready to manage without them, but leaving still feels like a promise broken.','Ask which promise they actually made','I promised to write and return if I could. I did not promise never to leave.'],
  ['song','The wrong verse','remembers a song differently from the version sung at the fair. The old verse names a household nobody mentions anymore.','Ask who taught them the old verse','A neighbor who sang softly while working. I want to remember their name beside it.'],
  ['boundary','A door kept closed','has refused a request from someone they love. The refusal was needed; the silence after it has been hard.','Ask what the boundary protects','Time I need for my own work. I want to keep loving them without becoming available for everything.'],
  ['failure','A practice that went badly','tried something important and failed in public. They want to try again before anyone turns the failure into their whole story.','Ask what they would change on the next attempt','The preparation, and whom I ask to watch. I do not need a promise that it will be easy.'],
  ['neighbor','A new voice next door','has a new neighbor whose customs feel unfamiliar. An invitation has been left at the door without a demand to accept it.','Ask what they would like to learn first','Their name, and what makes them feel welcome. I can ask about the customs after that.'],
  ['justice','The keeper’s account','has heard an accusation against a market keeper. The story is vivid, but nobody will name a witness.','Ask which parts can be checked','The fee is written down. The accusation is not. I should keep those apart until someone gives an account.'],
  ['growing','A childhood place revisited','returned to a place they knew as a child. It felt smaller, and one familiar doorway was gone.','Ask what they hoped to find there','A feeling I cannot carry back unchanged. There are people I could visit instead of asking the walls to remember me.'],
  ['gift','A gift with no debt','has been offered a costly gift by someone who has not stated what they expect in return.','Ask whether the giver will state the terms','I would rather hear an awkward answer than find an obligation hidden inside a kindness.'],
  ['mourning','A name said at supper','misses someone while ordinary meals and work continue. They are tired of being asked whether they have moved on.','Invite them to tell one memory','They always kept the smallest chipped bowl. I still look for it when I set the table.'],
  ['letters','The unanswered letter','has left a letter unanswered because every possible opening sounds either too cold or too eager.','Ask what they want the letter to do','Let the other person know I still think of them. Perhaps I can begin with that.'],
  ['rest','A day nobody bought','has kept one afternoon free and does not know how to use it. Being useful has become easier than knowing what they enjoy.','Ask what they liked before it became work','Listening at the fair. I used to stay for the last singer even when I knew none of the verses.'],
  ['friendship','A friendship changing shape','has less in common with an old friend than before. They still care for the person who remembers their younger life.','Ask what they still enjoy together','A walk with no task waiting at the end. We can disagree about the rest and still have that.'],
  ['promise','The promise they declined','was asked for a promise they could not keep. Someone called their honest refusal disloyal.','Ask what they can actually offer','One evening and a careful answer. I would rather give that than disappear behind a grand promise.'],
  ['tastes','A dish brought home','has learned to cook a dish from a traveler. Someone insists it can never belong at a local table.','Ask whose table they want it on','Mine, first. Sharing it can be an invitation without pretending I invented it.'],
  ['doubt','A belief with a question inside','has begun to question a familiar belief. They are afraid that admitting uncertainty will be mistaken for contempt.','Ask which part still matters to them','The care people gave each other while practicing it. I want room to ask about the rest.'],
  ['winter','A small plan for winter','is planning a winter that includes work, sleep, and one thing worth looking forward to. Their last plan only included work.','Ask what they want to look forward to','An evening with the people I keep postponing. I want to put it in the account before the paid work fills every line.'],
  ['apprentice','The question after the lesson','was asked a question by a learner that their own teacher never answered. They could repeat the old certainty or admit the gap.','Ask what they actually know','Enough to show how I test it. The learner deserves to see where my answer stops.'],
  ['age','The years between two names','noticed that a familiar name in a record belonged to someone younger than they are now. The age made an old story feel different.','Ask what changed when they saw the age','I stopped imagining someone finished and fearless. They were still becoming themselves too.'],
]);
const has=(s,p,t)=>s.conversations.seen.includes(`${p.id}:${t}`);
const ch=(id,label,description,text,response,effect)=>({id,label,description,text,response,effect});
export function personalScene(s,p){
  const pending=s.conversations.pending, h=(s.stories?.history||[]).filter(h=>h.personId===p.id&&['care','enterprise','coercion'].includes(h.choice)).reverse().find(h=>pending?.nodeId==='personal_v14_return'?pending.topic===`personal-return-${h.id}`:!has(s,p,`personal-return-${h.id}`));
  if(h&&(!pending||pending.nodeId==='personal_v14_return')){
    const hurt=h.choice==='coercion';
    return {nodeId:'personal_v14_return',topic:`personal-return-${h.id}`,title:'The account they kept',body:`${p.name} returns to ${h.title}. ${h.text}\n\n${hurt?'“I remember the pressure. Being able to answer now does not mean I agreed then. What do you have to say about it?”':'“We made a choice then. I want to know what it means to you after living with it.”'}`,choices:[
      ch('listen',hurt?'Acknowledge the harm without asking for forgiveness':'Ask how the choice affected their own life','Gain 5 bond. Earlier consequences and records remain; this reply does not undo them.',hurt?'I used pressure. You did not owe me consent or affection, and I cannot ask a sentence to erase it.':'Tell me what changed for you afterward, including the parts I did not see.',hurt?'I needed you to name it without making my forgiveness the next thing you demanded.':'I have my own account of it. I am glad you want to hear it.',{bond:5,fact:`return_${h.arcId}_${h.chapter}`,memory:`We returned honestly to ${h.title}.`}),
      ch('differ','Explain what you would choose differently now','Gain 2 bond. State a change of judgment; a later action is still needed to make repair.','I would choose differently now. I want my next action to show it, instead of asking you to take my word.', 'Then let the next action speak. I will keep my own memory of the earlier one.',{bond:2,memory:`You reconsidered your part in ${h.title}.`}),
      ch('boundary','Hear their boundary and leave the decision with them','Respect a limit without claiming a reconciliation. Gain 3 bond.','You can decide what you want from this relationship. I will hear the limit you set.','I want time before another agreement. That is the answer I can give now.',{bond:3,fact:`boundary_${h.arcId}`,memory:`You heard my boundary after ${h.title}.`}),
      ch('pressure','Demand that they accept your account','Lose 10 bond. This participant records another attempt to pressure them.','I have explained it. You should accept my account and stop bringing yours back.','You do not get to choose what I remember.',{bond:-10,fact:'repeated_pressure',memory:`You demanded that I surrender my account of ${h.title}.`}),
    ]};
  }
  const slot=pending?.nodeId?.startsWith('personal_v14_')?Number(pending.topic.split('-').at(-1)):Array.from({length:2},(_,n)=>n).find(n=>!has(s,p,`personal-${s.age}-${n}`));
  if(!Number.isInteger(slot)||slot<0||slot>1)return null;
  const deck=[...PERSONAL_TOPICS].sort((a,b)=>seededRoll(s.seed,`personal-deck:${p.id}:${a[0]}`,1000000)-seededRoll(s.seed,`personal-deck:${p.id}:${b[0]}`,1000000)||a[0].localeCompare(b[0]));
  const data=pending?PERSONAL_TOPICS.find(t=>pending.nodeId===`personal_v14_${t[0]}`):deck[((s.age-18)*2+slot)%deck.length];
  if(!data)return null;
  const place=s.world.locations.find(l=>l.id===p.locationId)?.name||'home',last=(p.source?.memories||[]).at(-1), independent=s.society?.people?.find(w=>w.sourcePersonId===p.id);
  const context=slot===0&&independent?` Their own present chapter: ${independent.goal}`:slot===1&&last?` One recent shared memory: ${last.slice(0,220)}`:'';
  return {nodeId:`personal_v14_${data[0]}`,topic:`personal-${s.age}-${slot}`,title:data[1],body:`At ${place}, ${p.name} ${data[2]}${context}`,choices:[
    ch('ask',data[3],'Gain 4 bond by asking about their own decision. No work, money or agreement is invented.','Tell me what matters to you in this.',data[4],{bond:4,memory:`We discussed ${data[1].toLowerCase()} and made room for my own answer.`}),
    ch('share','Share a related experience of your own','Gain 2 bond. Share company without claiming that the experiences are identical.','Something in that feels familiar. I can tell you my experience, then hear how yours differs.','I would like that. There can be room for two different accounts.',{bond:2,memory:`We compared different experiences while discussing ${data[1].toLowerCase()}.`}),
    ch('differ','Disagree and hear their answer','Gain 1 bond. They retain their own judgment and can decline your advice.','I see this differently. I can explain why, if you want to hear it.','I will hear you. I may still choose another way.',{bond:1,memory:`We disagreed about ${data[1].toLowerCase()} without surrendering our choices.`}),
    ch('pressure','Make their worry a bargaining piece','Lose 8 bond. This named person remembers your demand; no unwitnessed global secret spreads.','I will listen if you agree to owe me a favor afterward.','Then listening is the thing you are selling. I am not agreeing to that.',{bond:-8,fact:'uses_vulnerability',memory:`You demanded a favor while I was worried about ${data[1].toLowerCase()}.`}),
  ]};
}
